-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhTW" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.warlock.dps.Name"] = "所有天賦樹"
L["rm.era.warlock.dps.Description"] = "1–60 級，所有天賦樹，也適用於專家模式與獨行模式伺服器；綜合 Wowhead、Icy Veins、Warcraft Tavern 與 模擬器。你施法或引導時會等待，單人時絕不搶別人正在戰鬥的怪物。夜幕的暗影冥思優先；以暗影灼燒與灼熱之痛收掉隊伍目標；單人時即將死亡的目標會使用吸取靈魂（為了取得靈魂碎片，或擁有強化吸取靈魂時）、暗影灼燒或焚燒，然後是魔杖，絕不施放新的持續傷害效果。移動時只用瞬發法術。三個以上敵人時：敵人在你身邊且你的生命力至少一半時使用地獄烈焰，否則使用火焰之雨。一個詛咒：團隊中沒有人施放時使用暗影詛咒或元素詛咒，長時間的精英戰鬥使用厄運詛咒，否則使用痛苦詛咒。划算時使用獻祭（毀滅、團隊中，或法力 40% 以上），腐蝕術，生命虹吸（團隊中只在有暗影易傷時）。單人時：黑暗契約、健康時使用生命分流、受傷時使用吸取生命、魔杖。其他情況使用暗影箭。提醒：魔甲術或惡魔皮膚、你的惡魔（單人時虛空行者、隊伍中小鬼、為惡魔犧牲使用魅魔）、惡魔支配、惡魔犧牲、詛咒增幅、生命力低時使用虛空行者的犧牲與治療石、生命通道。詛咒分配、對逃跑的怪物使用魯莽詛咒、恐懼術、放逐術、靈魂石與製造治療石由你自行處理。"
L["rm.era.warlock.dps.icyveins.Name"] = "團隊中只用詛咒與腐蝕術（Icy Veins）"
L["rm.era.warlock.dps.icyveins.Description"] = "Icy Veins 針對有 16 個減益效果上限之伺服器的清單，作為推薦的術士內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。團隊中只用你的詛咒與腐蝕術，然後是暗影箭，不使用獻祭與生命虹吸。升級與地城的打法與推薦的內建循環相同。"
L["rm.era.warlock.dps.warcrafttavern.Name"] = "吸血坦（Warcraft Tavern）"
L["rm.era.warlock.dps.warcrafttavern.Description"] = "Warcraft Tavern 的升級打法，作為推薦的術士內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。小鬼，20 級起改用魅魔。獻祭、生命虹吸與腐蝕術，然後單人時在學會第四級吸取生命後以它作為填充（之前用魔杖），生命力接近全滿時就使用生命分流，在寵物法力滿之前使用黑暗契約。團隊中施放欄位允許的所有持續傷害效果，然後使用暗影箭。收尾技能、詛咒與安全提醒與推薦的內建循環相同；恐懼第二隻怪物由你自行處理。"
L["rm.forever.warlock.dps.Name"] = "所有天賦樹"
L["rm.forever.warlock.dps.Description"] = "適用於 1 至 60 級的所有術士天賦樹，綜合 Icy Veins、Wowhead 與 Method；某個天賦樹的步驟會在你學會它的天賦法術後出現。以獻祭與痛苦災厄拉怪（毀滅預先施放暗影箭），利用夜幕與屠虐的觸發，以灼熱之痛維持惡魔烙印。移動時只施放瞬發法術。怪群時：隊伍中地獄烈焰、火焰之雨、腐蝕術與痛苦災厄。接著對精英與首領使用末日災厄，否則使用痛苦災厄，隊伍中與對精英使用元素詛咒，獻祭、腐蝕術、生命虹吸、焚燒與暗影灼燒；單人時以毀壞、吸取生命（需有吸取天賦）或魔杖填充；否則使用燒盡或暗影箭。提醒：護甲、一隻惡魔（魅魔，否則虛空行者，再否則小鬼）、惡魔支配、搭配惡魔契印的惡魔犧牲、靈魂鏈結、武器石、詛咒增幅以及對第二個敵人使用浩劫之禍。由你自行處理：派寵物攻擊、其他詛咒、恐懼術、治療石與其他目標。在永久版本中，插件看不到生命力與法力，因此斬殺階段（吸取靈魂、以暗影灼燒作為致命一擊）、生命分流、生命通道與受傷時吸取都由你決定。"
L["rm.forever.warlock.dps.icyveins.Name"] = "所有天賦樹（Icy Veins）"
L["rm.forever.warlock.dps.icyveins.Description"] = "Icy Veins 的術士升級打法：魔杖是單人時的填充，虛空行者是預設惡魔，痛苦與毀滅會犧牲惡魔並在沒有惡魔的情況下作戰（分別從 41 級與 55 級起），惡魔學識維持惡魔烙印，且只把獻祭當作填充，毀滅在學會燒盡後，會對怪群中最耐打的敵人施放浩劫之禍，並在冷卻結束時使用焚燒。如果你遵循 Icy Veins，請選擇它而非推薦的術士內建循環。在永久版本中，插件看不到生命力、法力與剩餘存活時間，因此受傷時吸取生命、生命分流，以及哪些目標能活得夠久而值得上持續傷害效果，都由你決定。這是推薦的術士傷害輸出內建循環的替代選項，預設為停用：啟用它並停用那個，或提高它的優先順序。"
L["rm.forever.warlock.dps.wowhead.Name"] = "所有天賦樹（Wowhead）"
L["rm.forever.warlock.dps.wowhead.Description"] = "Wowhead 的 30 級術士：痛苦與惡魔學識帶著魅魔進行吸血坦打法（腐蝕術與痛苦災厄，不用獻祭，接著在剩餘戰鬥中使用吸取生命；在永久版本中生命力與法力是隱藏的，因此生命分流由你決定），惡魔學識維持惡魔烙印，且只對高血量目標施放痛苦災厄，毀滅對每隻怪物施放痛苦災厄、腐蝕術與獻祭，在獻祭結束前使用焚燒，把暗影灼燒留作最後一擊，並帶著虛空行者使用魔杖。詛咒增幅每次冷卻結束即使用；元素詛咒與末日災厄只用於精英與首領；沒有怪群部分。Wowhead 的指南只寫到 30 級。這是推薦的術士傷害輸出內建循環的替代選項，預設為停用：啟用它並停用那個，或提高它的優先順序。"
L["rm.mop.warlock.affliction.Name"] = "推薦"
L["rm.mop.warlock.affliction.Description"] = "推薦 10 至 90 級的痛苦使用（在痛苦專精下選用）。預先施放蝕魂術或痛苦動盪，對新的精英目標以靈魂炙燃與靈魂調換開場，維持痛苦、腐蝕術與痛苦動盪（黑闇之魂:悲慘期間提早刷新），蝕魂術即將結束且你有兩片靈魂裂片時（或黑闇之魂期間）施放蝕魂術，蝕魂術即將結束且你沒有靈魂裂片時引導吸取靈魂以獲得裂片，低於 20% 時使用吸取靈魂，否則使用惡毒之握（42 級前為暗影箭）。三個以上敵人時使用腐蝕種子（六個時搭配靈魂炙燃）。移動時：瞬發法術與魔化烈焰。提醒：你的惡魔、黑暗意圖、隊伍中使用元素詛咒、黑闇之魂、末日守衛或煉獄火、服侍魔典或犧牲魔典、生命分流、防禦技能。由你自行處理：將持續傷害效果擴散到其他目標，以及在目標之間使用靈魂調換。"
L["rm.mop.warlock.affliction.warcrafttavern.Name"] = "保留蝕魂術（Warcraft Tavern）"
L["rm.mop.warlock.affliction.warcrafttavern.Description"] = "預設關閉。Warcraft Tavern 與 Method 的靈魂裂片策略：持續傷害效果維持方式與推薦的痛苦內建循環相同，但蝕魂術保留到四片靈魂裂片或黑闇之魂:悲慘期間，且低於 20% 時，只要你有靈魂裂片，就以靈魂炙燃與靈魂調換刷新所有持續傷害效果。要使用它，請啟用它並停用推薦的痛苦內建循環。"
L["rm.mop.warlock.demonology.Name"] = "推薦"
L["rm.mop.warlock.demonology.Description"] = "推薦 10 至 90 級的惡魔學識使用（在惡魔學識專精下選用）。施法者形態下：腐蝕術，依充能使用古爾丹之手，一層的暗影之焰即將消失時再施放一次古爾丹之手然後進入惡魔化身，搭配黑闇之魂:知識（或惡魔之怒接近全滿時）使用惡魔化身，兩層熔火之心或低於 25% 時使用靈魂之火，四個以上敵人時使用地獄烈焰，暗影箭。惡魔化身期間：末日，以混沌之觸維持腐蝕術，熔火之心觸發時使用靈魂之火，怪群時使用獻祭光環或虛無射線，混沌之觸，並在黑闇之魂未生效且惡魔之怒在 300 以下時提示你退出。提醒：惡魔守衛（或憤怒守衛）、黑暗意圖、黑闇之魂、小鬼群、魔典:惡魔守衛、末日守衛或煉獄火、生命分流、單人時使用生命通道。由你自行處理：惡魔風暴（寵物自動施放）與惡魔飛躍。"
L["rm.mop.warlock.demonology.guide.Name"] = "保留熔火之心（指南）"
L["rm.mop.warlock.demonology.guide.Description"] = "預設關閉。指南的共識（Method、wowtbc.gg、Warcraft Tavern、Wowhead）：與推薦的惡魔學識內建循環相同，只是施法者形態下惡魔化身會等到 900 點惡魔之怒或黑闇之魂，而靈魂之火只在八層熔火之心或低於 25% 時施放，讓層數在惡魔形態下消耗。要使用它，請啟用它並停用推薦的惡魔學識內建循環。"
L["rm.mop.warlock.destruction.Name"] = "推薦"
L["rm.mop.warlock.destruction.Description"] = "適用於 10 至 90 級的毀滅（在毀滅專精下選用）。預先施放燒盡，維持獻祭，絕不讓焚燒停在兩層充能，在 3.5 燃火餘燼或黑闇之魂:易變期間將餘燼用於混沌箭（低於 20% 時用暗影灼燒），以燒盡消耗爆燃，並以燒盡填充；即將死亡的目標使用暗影灼燒。三個以上敵人時：火焰之雨，四個時使用硫磺與火焰，然後是獻祭、焚燒與燒盡，並在你的餘燼用完時提示關閉硫磺與火焰。移動時：暗影灼燒、焚燒、魔化烈焰。提醒：你的惡魔或犧牲魔典、克索諾斯之焰、黑暗意圖、黑闇之魂、兩個以上敵人時使用浩劫（請自行對第二個目標施放）、末日守衛或煉獄火、餘燼分流與防禦技能。"
L["rm.mop.warlock.unspecialized.Name"] = "未選擇專精"
L["rm.mop.warlock.unspecialized.Description"] = "適用於沒有專精的術士（1 至 9 級，或之後尚未選擇專精前）。以腐蝕術拉怪並維持，生命力低於一半時使用吸取生命，暗影箭。提醒：單人時使用虛無行者（隊伍中使用小鬼），以及兩次拉怪之間使用治療石。"
L["rm.retail.warlock.affliction.Name"] = "暴雪戰鬥助手"
L["rm.retail.warlock.affliction.Description"] = "推薦至暗之夜的痛苦專精使用。在戰鬥中，遊戲現在會對插件隱藏你的持續傷害效果、觸發效果、冷卻時間與生命力，因此它會顯示暴雪自己的戰鬥助手建議（一鍵循環，它會維持痛苦與腐蝕術、把靈魂裂片花在痛苦動盪上，並處理犧牲魔典），並在你施法、引導或沒有選取敵人時停止。提醒它未包含的內容：戰鬥中的召喚暗凝、兩波拉怪之間召喚惡魔獵犬（除非你已犧牲了惡魔）、對可中斷的施法使用惡魔號令（只會在遊戲允許讀取該施法的場合亮起）、戰鬥中只要就緒就使用黑暗契約與心志堅定（正式版中生命力是隱藏的，因此何時使用由你決定）。"
L["rm.retail.warlock.affliction.icyveins.Name"] = "參考（Icy Veins）"
L["rm.retail.warlock.affliction.icyveins.Description"] = "僅供參考，預設關閉：Icy Veins 與 SimulationCraft（靈魂收割者）的施放順序需要讀取持續傷害效果的計時、夜暮與裂片易變，而至暗之夜會在戰鬥中隱藏它們。拉怪前使用蝕魂術；面對三個以上交戰中的敵人且沒有你的腐蝕術時使用腐蝕種子；蝕魂術；痛苦以及腐蝕術或枯萎剩餘不到 3 秒時刷新；靈魂裂片不超過兩個時使用黑暗收割；5 個靈魂裂片時使用痛苦動盪；兩層夜暮時使用惡毒之握，否則使用暗影箭；裂片易變觸發或 4 個靈魂裂片時使用痛苦動盪；吸取靈魂；暗影箭。提醒：黑暗收割進入冷卻後使用召喚暗凝、惡意、召喚惡魔獵犬，以及共用提醒。"
L["rm.retail.warlock.demonology.Name"] = "暴雪戰鬥助手"
L["rm.retail.warlock.demonology.Description"] = "推薦至暗之夜的惡魔學識專精使用。顯示暴雪的戰鬥助手建議（召喚恐懼潛獵犬、古爾丹之手、惡魔箭、魔能虹吸與惡魔暴君），並在你施法、引導或沒有選取敵人時停止。提醒它未包含的內容：你在最近 12 秒內召喚的恐懼潛獵犬仍在場時使用召喚惡魔暴君、戰鬥中的魔典：小鬼領主、魔典：魔化劫毀者與召喚末日守衛、兩波拉怪之間召喚惡魔守衛、惡魔號令、黑暗契約、心志堅定。"
L["rm.retail.warlock.demonology.icyveins.Name"] = "參考（Icy Veins）"
L["rm.retail.warlock.demonology.icyveins.Description"] = "僅供參考，預設關閉：Icy Veins 與 SimulationCraft（崇魔者）的施放順序需要讀取魔能之核、小鬼數量與冷卻計時，而至暗之夜會在戰鬥中隱藏它們。拉怪前使用魔能虹吸、惡魔箭與暗影箭；接著魔能之核不超過一層時使用魔能虹吸，魔典：小鬼領主，魔典：魔化劫毀者，召喚末日守衛，召喚恐懼潛獵犬，5 個靈魂裂片時使用召喚惡魔暴君，面對三個以上交戰中的敵人時使用小鬼爆破，禍滅，3 個以上靈魂裂片時使用古爾丹之手，少於 3 個時使用煉獄箭，魔能之核觸發且靈魂裂片少於 4 個時使用惡魔箭，暗影箭。"
L["rm.retail.warlock.destruction.Name"] = "暴雪戰鬥助手"
L["rm.retail.warlock.destruction.Description"] = "推薦至暗之夜的毀滅專精使用。顯示暴雪的戰鬥助手建議（獻祭或枯萎、焚燒、混沌箭、火焰之雨、靈魂之火、惡意），並在你施法、引導或沒有選取敵人時停止。提醒它未包含的內容：戰鬥中的召喚煉獄火、兩波拉怪之間召喚小鬼（除非你已犧牲了惡魔）、惡魔號令、黑暗契約、心志堅定。對第二個目標使用浩劫由你自行處理。"
L["rm.retail.warlock.destruction.icyveins.Name"] = "溢出前使用混沌箭參考（Icy Veins）"
L["rm.retail.warlock.destruction.icyveins.Description"] = "僅供參考，預設關閉：Icy Veins 的喚魔者施放順序，會在靈魂裂片溢出前把它們花在混沌箭上，並在冷卻結束時就使用暗影灼燒與引導惡魔火焰。面對三個以上交戰中的敵人時使用火焰之雨；維持枯萎或獻祭；召喚煉獄火；惡意；暗影灼燒；靈魂裂片少於 4 個時使用靈魂之火；4 個以上時使用混沌箭；災變；少於 4 個時使用煉獄箭；引導惡魔火焰；焚燒；燒盡。"
L["rm.retail.warlock.destruction.simc.Name"] = "參考（SimulationCraft）"
L["rm.retail.warlock.destruction.simc.Description"] = "僅供參考，預設關閉：SimulationCraft 的施放順序需要讀取獻祭、爆燃、充能與冷卻計時，而至暗之夜會在戰鬥中隱藏它們。拉怪前使用靈魂之火與燒盡；面對三個以上交戰中的敵人時，3 個靈魂裂片時使用火焰之雨，並使用災變；接著靈魂裂片不超過 4 個時使用靈魂之火，只在 5 個時使用混沌箭，兩層充能時或靈魂裂片少於 4 個且沒有爆燃時使用焚燒，召喚煉獄火，惡意，枯萎或獻祭剩餘最後 30% 時刷新，禍滅，災變，靈魂裂片不超過 3 個時使用煉獄箭，燒盡。"
L["rm.retail.warlock.initial.Name"] = "暴雪戰鬥助手"
L["rm.retail.warlock.initial.Description"] = "在你選擇專精之前推薦使用（此時遊戲回報的是術士的初始專精）。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時附上每個術士內建循環共用的提醒，各項在你學會對應法術後才會出現。當你在 10 級選擇專精後，該專精的內建循環會接手。"
L["rm.sod.warlock.fire.Name"] = "火焰（探索賽季）"
L["rm.sod.warlock.fire.Description"] = "探索賽季的毀滅，已紋刻混沌箭或燒盡時選用；綜合 模擬器 第 6 階段與 Wowhead。以暗影灼燒與灼熱之痛收尾；移動時使用瞬發法術；怪群時使用燒盡的增益效果、火焰之湖與地獄烈焰；一個詛咒（隊伍中沒有人施放時用魯莽詛咒，長時間精英戰鬥用厄運詛咒，否則用痛苦詛咒）；焚燒只用來維持爆燃；維持獻祭與燒盡的增益效果；低於 35% 時在屠虐期間以靈魂之火取代混沌箭；靈魂之火！觸發；混沌箭；單人時引導大師的吸取生命與生命分流；燒盡（紋刻前用暗影箭）。提醒：魔化護甲、小鬼、詛咒增幅以及安全提醒。"
L["rm.sod.warlock.fire.icyveins.Name"] = "火焰，焚燒冷卻結束即使用（探索賽季，Icy Veins）"
L["rm.sod.warlock.fire.icyveins.Description"] = "Icy Veins 與 Warcraft Tavern 的探索賽季毀滅，作為推薦的探索賽季火焰內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。維持獻祭，焚燒與混沌箭冷卻結束即使用（低於 35% 時也使用混沌箭），燒盡的增益效果，低於 35% 時在屠虐期間使用靈魂之火，燒盡作為填充；傷害詛咒只在移動時使用，隊伍中沒有人施放魯莽詛咒時則用魯莽詛咒。"
L["rm.sod.warlock.shadow.Name"] = "暗影，痛苦與惡魔守衛（探索賽季）"
L["rm.sod.warlock.shadow.Description"] = "探索賽季的痛苦與惡魔守衛配置，也是沒有其他內建循環適用時所有探索賽季術士的預設循環；綜合 模擬器 第 6 階段、Wowhead 與 Icy Veins。夜幕觸發；以暗影灼燒或吸取靈魂收掉隊伍目標；單人時即將死亡的目標使用吸取靈魂而非持續傷害效果；移動時使用瞬發法術；怪群時使用火焰之湖與地獄烈焰；一個詛咒（隊伍中沒有人施放時用魯莽詛咒，否則用痛苦詛咒）；痛苦動盪、引導大師的吸取生命、暗影之焰（之前用獻祭）、腐蝕術、蝕魂術、生命虹吸（已紋刻召請時，每個都在剩餘不到 6 秒時續上）；已紋刻靈魂虹吸時，低於 20% 使用吸取靈魂；單人時的續航與魔杖；暗影箭。提醒：魔化護甲、你的惡魔（紋刻後為惡魔守衛）、寵物法力不足時使用生命分流、詛咒增幅以及安全提醒。詛咒分配與對怪群使用暗影箭雨由你自行處理。"
L["rm.sod.warlock.shadow.simulator.Name"] = "暗影，吸取靈魂填充（探索賽季，模擬器）"
L["rm.sod.warlock.shadow.simulator.Description"] = "模擬器 第 6 階段針對靈魂虹吸配置的痛苦清單，作為推薦的探索賽季暗影內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。無論生命力多少，都以吸取靈魂作為填充，下一個步驟一到時就會顯示，讓你可以為它中斷引導；其他任何引導則讓它完成。痛苦動盪與暗影之焰在剩下 7.5 秒時續上，痛苦詛咒與腐蝕術在剩下 6 秒時續上，引導大師的吸取生命，蝕魂術，暗影箭只在暗影冥思觸發時使用，生命虹吸，法力低於 10% 時使用生命分流。提醒與推薦的內建循環相同。"
L["rm.sod.warlock.tank.Name"] = "坦克（探索賽季，惡魔化身）"
L["rm.sod.warlock.tank.Description"] = "探索賽季的坦克，已紋刻惡魔化身時選用；綜合 模擬器、Icy Veins、Wowhead 與 Warcraft Tavern。防衛者的決心缺少或即將結束時使用暗影順劈斬，靈魂之火！觸發，使用燒盡以維持其火焰增益效果；三個以上敵人時使用暗影順劈斬、火焰之湖、暗影之焰與地獄烈焰。接著施放一個詛咒（痛苦詛咒，否則在沒有人施放時用魯莽詛咒），暗影之焰（紋刻前用獻祭），引導大師的吸取生命，腐蝕術，生命虹吸，為了爆燃使用焚燒，低於 35% 時在屠虐期間使用靈魂之火，並以灼熱之痛作為威脅值填充。提醒：惡魔化身、魔化護甲、你的惡魔、獻祭光環、魔化恩典、生命力低時使用復仇、目標攻擊其他人時使用破膽威嚇、怪群時使用惡魔長嘯、詛咒增幅、寵物法力不足時使用生命分流。煉獄護甲由你自行處理。"
L["rm.tbc.warlock.dps.icyveins.Name"] = "所有天賦樹（Icy Veins）"
L["rm.tbc.warlock.dps.icyveins.Description"] = "1 至 70 級的所有天賦樹。詛咒，接著隨著學會依序加入痛苦動盪、獻祭、腐蝕術與生命虹吸，暗影箭或燒盡；夜幕與反衝觸發優先；三個以上敵人時使用腐蝕種子、地獄烈焰與暗影之怒。單人時受傷會吸取生命，會使用生命分流與魔杖，並對瀕死目標使用吸取靈魂或收尾法術。提醒：獄甲術、魔甲術或惡魔皮膚、你的惡魔、惡魔犧牲、靈魂鏈結、詛咒增幅與靈魂粉碎。恐懼術與其他詛咒由你自行處理。"
L["rm.tbc.warlock.dps.wowhead.Name"] = "吸血坦（Wowhead）"
L["rm.tbc.warlock.dps.wowhead.Description"] = "依據 Wowhead 指南的術士，作為推薦的 Icy Veins 術士內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。單人時採用吸血坦打法：持續傷害效果都上齊後以吸取生命作為填充，獻祭與生命虹吸留給精英怪。隊伍中一律施放獻祭，排在腐蝕術與生命虹吸之後。其餘與推薦的內建循環相同。"
